# does some avaraging
def avg(data, chunk_size):
    avg_vals = []
    avg_val = 0
    #this should round one does not care to much since the data loss should be minimal even if this happens since at max 1 sample is lost at the end
    for chunk in range(0, int(len(data)/chunk_size)):
        avg_val = np.average(data[chunk*chunk_size:(chunk+1)*chunk_size])
        # not optimal since increase runtime but should be fine?
        for _ in range(0,chunk_size):
            avg_vals.append(avg_val)
    if(len(data) > len(avg_vals)):
        avg_vals.append(avg_val) # because for some reason this is an uneven number ? ( sometimes)
    return avg_vals



t = 10000000 # memory depth
sr = 1.25e9 # 1.25GSa/s
sr_1_2 = 625e6 # 625 MSa/s



magnitude_dBV_no_paper, freqs_no_paper = run_fft(y_no_paper, sr_1_2)
magnitude_dBV_paper, freqs_paper= run_fft(y_with_paper, sr_1_2)



avg_no_paper = avg(magnitude_dBV_no_paper, 5)
avg_paper = avg(magnitude_dBV_paper, 5)

avarage_no_paper = np.average(magnitude_dBV_no_paper)
avarage_paper = np.average(magnitude_dBV_paper)


print(f"Differenz zwischen keinem Paper : {avarage_no_paper.astype(float)}dB\nUnd mit Papier : {avarage_paper.astype(float)}dB \nDie Differenz zwischen beiden ist {avarage_no_paper.astype(float)-avarage_paper.astype(float)} dB")

fig, axs = plt.subplots(2)
axs[0].plot(freqs_no_paper/1e6 , magnitude_dBV_no_paper,color='b' ,label="FFT no paper")
axs[0].plot(freqs_paper/1e6, magnitude_dBV_paper, color='r',label="FFT paper")
axs[0].set_ylabel("in dBV")
axs[0].set_xlabel("in MHz")
axs[0].set_title("FFT")

axs[1].axhline(avarage_no_paper, color='slateblue', label="Avg no paper") # horizontal
