axs[1].plot(freqs_no_paper /1e6, avg_no_paper, color='b', label=" no paper ")
axs[1].plot(freqs_paper/1e6 , avg_paper, color='r', label=" paper")
axs[1].set_ylabel("in dBV")
axs[1].set_xlabel("in MHz")
